#include <queue>
#include <vector>
using namespace std;
class Solution {
public:
    int maximumTotalValue(vector<int>& value, vector<int>& decay, int m) {
        const long long MOD = 1000000007LL;
        priority_queue<pair<long long,int>> pq;
        for (int i = 0; i < (int)value.size(); ++i)
            pq.push({value[i], i});
        long long ans = 0;
        for (int t = 0; t < m && !pq.empty(); ++t) {
            auto [g, i] = pq.top(); pq.pop();
            if (g <= 0) break;
            ans = (ans + g) % MOD;
            pq.push({g - decay[i], i});
        }
        return (int)ans;
    }
};

