import java.util.PriorityQueue;
class Solution {
    public int maximumTotalValue(int[] value, int[] decay, int m) {
        final long MOD = 1000000007L;
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(b[0], a[0]));
        for (int i = 0; i < value.length; i++) pq.add(new long[]{value[i], i});
        long ans = 0;
        for (int t = 0; t < m && !pq.isEmpty(); t++) {
            long[] top = pq.poll();
            long g = top[0]; int i = (int) top[1];
            if (g <= 0) break;
            ans = (ans + g) % MOD;
            pq.add(new long[]{g - decay[i], i});
        }
        return (int) ans;
    }
}

