var maximumTotalValue = function(value, decay, m) {
    const MOD = 1000000007n;
    let heap = value.map((v, i) => [BigInt(v), i]);
    const sift = (h, i) => {
        while (true) {
            let l = 2*i+1, r = 2*i+2, s = i;
            if (l < h.length && h[l][0] > h[s][0]) s = l;
            if (r < h.length && h[r][0] > h[s][0]) s = r;
            if (s === i) break;
            [h[i], h[s]] = [h[s], h[i]]; i = s;
        }
    };
    for (let i = heap.length - 1; i >= 0; i--) sift(heap, i);
    let ans = 0n;
    for (let t = 0; t < m && heap.length; t++) {
        const [g, i] = heap[0];
        if (g <= 0n) break;
        ans = (ans + g) % MOD;
        heap[0] = [g - BigInt(decay[i]), i];
        sift(heap, 0);
    }
    return Number(ans);
};

