class Solution {
public:
    int maximumTotalValue(vector<int>& value, vector<int>& decay, int m) {
        const long long MOD = 1000000007LL;
        int n = value.size();
        auto countSum = [&](long long x, long long& cnt) -> long long {
            long long s = 0;
            cnt = 0;
            for (int i = 0; i < n; ++i) {
                long long v = value[i], d = decay[i];
                if (v >= x) {
                    long long k = (v - x) / d + 1;
                    cnt += k;
                    s = (s + (k % MOD) * (v % MOD)) % MOD;
                    long long half = (k * (k - 1) / 2) % MOD;
                    s = (s - (d % MOD) * half % MOD + MOD) % MOD;
                }
            }
            return s;
        };
        long long cnt;
        long long s1 = countSum(1, cnt);
        if (cnt <= m) return (int)s1;
        long long lo = 1, hi = *max_element(value.begin(), value.end());
        while (lo < hi) {
            long long mid = (lo + hi + 1) / 2;
            countSum(mid, cnt);
            if (cnt >= m) lo = mid; else hi = mid - 1;
        }
        long long c;
        long long s = countSum(lo + 1, c);
        long long fill = (m - c) % MOD;
        long long ans = (s + fill * (lo % MOD)) % MOD;
        return (int)ans;
    }
};

