class Solution {
    private int[] value, decay;
    private static final long MOD = 1000000007L;

    private long[] countSum(long x) {
        long cnt = 0, s = 0;
        for (int i = 0; i < value.length; i++) {
            long v = value[i], d = decay[i];
            if (v >= x) {
                long k = (v - x) / d + 1;
                cnt += k;
                s = (s + (k % MOD) * (v % MOD)) % MOD;
                long half = (k * (k - 1) / 2) % MOD;
                s = (s - (d % MOD) * half % MOD + MOD) % MOD;
            }
        }
        return new long[]{cnt, s};
    }

    public int maximumTotalValue(int[] value, int[] decay, int m) {
        this.value = value; this.decay = decay;
        long[] cs = countSum(1);
        if (cs[0] <= m) return (int) cs[1];
        long lo = 1, hi = 0;
        for (int v : value) hi = Math.max(hi, v);
        while (lo < hi) {
            long mid = (lo + hi + 1) / 2;
            if (countSum(mid)[0] >= m) lo = mid; else hi = mid - 1;
        }
        long[] res = countSum(lo + 1);
        long ans = (res[1] + ((m - res[0]) % MOD) * (lo % MOD)) % MOD;
        return (int) ans;
    }
}

