var maximumTotalValue = function(value, decay, m) {
    const MOD = 1000000007n;
    const B = Array.from(value, BigInt), D = Array.from(decay, BigInt), M = BigInt(m);
    const countSum = (x) => {
        let c = 0n, s = 0n;
        for (let i = 0; i < B.length; i++) {
            if (B[i] >= x) {
                const k = (B[i] - x) / D[i] + 1n;
                c += k;
                s += k * B[i] - D[i] * k * (k - 1n) / 2n;
            }
        }
        return [c, ((s % MOD) + MOD) % MOD];
    };
    let [c1, s1] = countSum(1n);
    if (c1 <= M) return Number(s1);
    let lo = 1n, hi = 0n;
    for (const v of B) if (v > hi) hi = v;
    while (lo < hi) {
        const mid = (lo + hi + 1n) / 2n;
        if (countSum(mid)[0] >= M) lo = mid; else hi = mid - 1n;
    }
    const [c, s] = countSum(lo + 1n);
    return Number((s + ((M - c) % MOD) * (lo % MOD)) % MOD);
};
